import { JOURNEY } from "@/components/cs-journey/journeyData";
import type { Track, TrackChapter } from "@/types/schema";

export const PALETTES = [
  { g1: "#fef9c3", g2: "#fde68a", g3: "#f59e0b", accent: "#92400e" }, // amber
  { g1: "#eff6ff", g2: "#93c5fd", g3: "#3b82f6", accent: "#1e40af" }, // blue
  { g1: "#f0fdfa", g2: "#5eead4", g3: "#0d9488", accent: "#134e4a" }, // teal
  { g1: "#fdf4ff", g2: "#d8b4fe", g3: "#9333ea", accent: "#581c87" }, // purple
  { g1: "#fff7ed", g2: "#fdba74", g3: "#ea580c", accent: "#7c2d12" }, // orange
  { g1: "#fff1f2", g2: "#fda4af", g3: "#e11d48", accent: "#881337" }, // rose
  { g1: "#f5f3ff", g2: "#c4b5fd", g3: "#7c3aed", accent: "#4c1d95" }, // violet
  { g1: "#f0fdf4", g2: "#86efac", g3: "#16a34a", accent: "#14532d" }, // emerald
] as const;

export function chapter(
  trackId: string,
  num: number,
  title: string,
  sub: string,
  desc: string,
  tags: string[],
  body: string
): TrackChapter {
  const p = PALETTES[(num - 1) % PALETTES.length];
  return {
    id: `${trackId}-${num}`,
    num: String(num).padStart(2, "0"),
    title,
    sub,
    desc,
    tags,
    body,
    ...p,
  };
}

export function buildTrack(
  id: string,
  title: string,
  tagline: string,
  chapters: TrackChapter[],
  ownerId: string | null = null,
  source: Track["source"] = "builtin",
  rawNotes: string | null = null
): Track {
  return {
    id,
    title,
    tagline,
    accentColor: chapters[0]?.g3 ?? "#f59e0b",
    source,
    ownerId,
    rawNotes,
    createdAt: "2026-01-01T00:00:00.000Z",
    chapters,
  };
}

// ── Python Fundamentals for DSA — reuses the hand-illustrated chapters ──────
const PYTHON_FUNDAMENTALS_BODIES = [
  "Every program starts with storing and naming information. A variable is a label pointing at a value in memory — `x = 42` doesn't just set `x`, it tells Python to create an integer object and bind the name `x` to it. Python is dynamically typed: the same name can point at an int, then a string, then a list, with no declaration required. Learn the core primitive types (`int`, `float`, `str`, `bool`), how `input()` and `print()` move data in and out of your program, and how expressions like `score * 2 + 1` get evaluated left to right by operator precedence. Get comfortable with f-strings (`f\"{name} scored {score}\"`) early — you'll use them constantly.",
  "Programs that only run top-to-bottom can't react to anything. `if`/`elif`/`else` blocks let your code branch based on a condition, and conditions are just expressions that evaluate to `True` or `False`. Comparison operators (`==`, `!=`, `<`, `>=`) build the conditions; `and`/`or`/`not` combine them. The single biggest beginner trap is confusing `=` (assignment) with `==` (comparison) — Python won't let you do it inside an `if`, but the habit matters for every language after this one. Practice nesting conditions and, just as importantly, practice *flattening* them — deeply nested if/else is usually a sign you can restructure with early returns.",
  "Loops are how a few lines of code do thousands of repetitions. `for` loops iterate over a known sequence (`for i in range(10)`, `for char in \"hello\"`); `while` loops repeat as long as a condition holds, which is what you want when you don't know the iteration count in advance (reading input until the user quits, searching until found). Learn `break` to exit early and `continue` to skip an iteration, and watch for the classic `while` bug: forgetting to update the condition variable, which spins forever. Nested loops (a loop inside a loop) are how you process grids and pairs — they're also where naive solutions get slow, a preview of Big-O thinking later in DSA.",
  "Functions are how you stop repeating yourself. `def greet(name): return f\"Hi {name}\"` packages logic behind a name you can call from anywhere, with parameters that make it reusable for different inputs. Understand the difference between *parameters* (the placeholders in the definition) and *arguments* (the real values you pass in), default arguments, and what a function returns when there's no explicit `return` (`None`). Pair this with Python's core collections — `list` for ordered, mutable sequences and `str` for immutable text — and their slicing syntax (`items[1:3]`, `name[::-1]`). Mastering list comprehensions (`[x*2 for x in items if x > 0]`) here will make every DSA problem you write afterward shorter and clearer.",
  "Lists get you far, but real data is rarely flat. Dictionaries (`{\"name\": \"Alice\", \"age\": 30}`) map keys to values in O(1) average lookup time — this is the single most important data structure for DSA interviews after arrays, because so many problems reduce to \"have I seen this before\" (use a dict or set). Tuples are like lists but immutable, which makes them safe to use as dict keys or to return multiple values from a function (`return min_val, max_val`). File I/O (`open(\"data.txt\") as f`) is how programs persist data beyond a single run — learn the `with` statement, which guarantees the file closes even if an error occurs partway through.",
  "Object-oriented programming lets you bundle data and the behavior that acts on it into one unit. A `class` is a blueprint; an *instance* (`dog1 = Dog()`) is a concrete object built from it. `self` refers to the specific instance a method is called on — it's how `dog1.bark()` and `dog2.bark()` can share one method definition but act on different data. Learn the constructor (`__init__`), instance attributes (`self.name = name`), and inheritance, where a subclass (`class Dog(Animal)`) reuses and extends a parent's behavior. You won't need heavy OOP for most DSA problems, but it's essential once you're organizing real applications instead of single-function scripts.",
  "This is where the pieces come together. Modules (`import random`, `import math`) let you pull in code other people wrote instead of reinventing it — and your own files can be imported the same way, which is how real projects are organized across many files instead of one giant script. Recursion is a function that calls itself with a smaller version of the problem until it hits a base case (`if n == 0: return 1`) — it's the foundation for tree traversal, divide-and-conquer, and a huge fraction of classic DSA problems. From here, the path forward is applying all of this to actual algorithms: sorting, searching, and the data structures (stacks, queues, trees, graphs) that the rest of your DSA prep will build on.",
];

const PYTHON_FUNDAMENTALS_TRACK: Track = buildTrack(
  "python-fundamentals-dsa",
  "Python Fundamentals for DSA",
  "The Python you need before data structures & algorithms.",
  JOURNEY.map((ch, i) =>
    chapter(
      "python-fundamentals-dsa",
      i + 1,
      ch.title,
      ch.sub,
      ch.desc,
      ch.tags,
      PYTHON_FUNDAMENTALS_BODIES[i]
    )
  )
);

// ── Python for AI ────────────────────────────────────────────────────────────
